    meta:      { hasKorean: false, hasMath: false, hasLinks: false, hasUnmapped: false, paraCount: 0, pkgs: {} },   // pkgs: extra preamble packages the escapers asked for (EXPORT_SYMBOL_MAP pkg); hasUnmapped: >= 1 \LFXmissing emitted (_exPlaceholder)
    seen:      { unicode: {}, cite: {}, strike: {}, oddDollar: {} },
    bibKeys:   null,     // Object of keys parsed from the .bib, or null when no .bib
    where:     null,
    runMode:      null,  // the _exEmitRuns mode being emitted ('para' | 'heading' | 'cell' | 'footnote')
    starHeadings: false, // the document numbers headings by hand → every heading starred (emitDoc)
    seenSection:  false, // a level-1 heading has been emitted (a subsection before it is starred)
    listCounts:   {},    // 'listId|level' → items emitted so far (numbering continues across interruptions)
    listGlyphs:   {},    // 'listId|level' → glyph kind of its last item (a slot level reopens with it)
    listOpens:    [],    // { at: ctx.lines index of a \begin{enumerate}, list, mark } — split lists get % lfx-list:<n>
    listLastOpen: {},    // 'listId|level' → the last listOpens entry of that level (a continuation marks it too)
