  // form of a heading is the heading, then its body as usual (R71: 1901.00082 kept the rest of a
  // subsection as code)
  const headingName = name.replace(/\*$/, '');
  if (_IP_HEADING_CMDS[headingName]) {
    let s = bodyStart;
    const opt = _ipReadOptional(src, s, bodyEnd); if (opt) s = opt.end;
    const g = _ipReadGroup(src, s, bodyEnd);
    const h = { t: 'heading', level: _IP_HEADING_CMDS[headingName],
                runs: g ? _ipParseInline(ctx, g.bodyStart, g.bodyEnd, { mode: 'heading', depth: 0 }) : [] };
    if (headingName !== name && _IP_HEADING_CMDS[headingName] < 4) h.numbered = false;   // \begin{section*}
    if (ctx.docx) h.docx = { cmd: headingName, star: headingName !== name };              // R210: \begin{subsection}{…} (1901.00082)
    pushBlock(h);
    ctx.stats.headings++;
    _ipParseBlocks(ctx, out, g ? g.end : s, bodyEnd, { nesting: o.nesting, align: o.align || null, float: o.float });
    return after;
  }
  if (name in _IP_TRANSPARENT_ENVS || _ipHas(IMPORT_LANG_NAMES, name)) {   // \begin{french}: polyglossia's form
    let s = bodyStart;
    if (name === 'otherlanguage' || name === 'otherlanguage*') { const g = _ipReadGroup(src, s, bodyEnd); if (g) s = g.end; }
    if (_ipHas(IMPORT_LANG_NAMES, name)) { const opt = _ipReadOptional(src, s, bodyEnd); if (opt) s = opt.end; }
    if (name === 'minipage') s = _ipSkipArgs(src, s, bodyEnd, 3);
    if (name === 'frame') { const opt = _ipReadOptional(src, s, bodyEnd); if (opt) s = opt.end; }
    const label = _IP_TRANSPARENT_ENVS[name];
    if (label) pushBlock({ t: 'para', align: 'center', runs: [{ t: 'txt', s: label, b: true }] });
    // quote / quotation / verse: a Quote container (v16 tree) — the encoder gives its blocks LaTeX's margins
    // and their path code, Export reads the environment back (R68g; nested quotes keep both, R95)
    if (LFX_QUOTE_INDENT[name]) {
      const node = { t: 'quote', kind: name, body: [] };
      _ipParseBlocks(ctx, node.body, s, bodyEnd, { nesting: o.nesting, align: null, float: o.float });
      if (node.body.length) pushBlock(node);
      return after;
    }
    _ipParseBlocks(ctx, out, s, bodyEnd, { nesting: o.nesting, align: o.align || null, float: o.float });
    return after;
  }
  if (ctx.docx && name === 'thebibliography') return _ipDocxBibliography(ctx, bodyStart, bodyEnd, o, pushBlock, after);
  let thmLabel = _IP_THEOREM_ENVS[name] || ctx.theoremEnvs[name];
  if (thmLabel) {
    // a \newtheorem label is LaTeX too: `{\thf Lemma}` with \thf a font switch printed
    // "\thf Lemma" as text (R71, 1901.00082) — read as text, formatting dropped
    if (thmLabel.indexOf('\\') >= 0 || thmLabel.indexOf('{') >= 0) {
      const lb = _ipNewBuilder();
      _ipParseInlineString(ctx, thmLabel, { mode: 'heading', depth: 0 }, {}, lb);
      const plain = lb.runs.map(function (r) { return r.t === 'txt' ? r.s : ''; }).join('').replace(/\s+/g, ' ').trim();
      if (plain) thmLabel = plain;
    }
    let s = bodyStart;
    const opt = _ipReadOptional(src, s, bodyEnd); if (opt) s = opt.end;
    const tmp = [];
    _ipParseBlocks(ctx, tmp, s, bodyEnd, { nesting: o.nesting, align: o.align || null, float: o.float });
    let num = '';
    const counter = ctx.theoremNumbering && ctx.theoremNumbering[name];
    if (ctx.docx) { if (ctx.docx.thm[name] && ctx.docx.thm[name].counter) num = '\uE012'; }   // R209: the writer numbers it
    else if (counter) {
      ctx.theoremCounters[counter] = (ctx.theoremCounters[counter] || 0) + 1;
      num = ' ' + ctx.theoremCounters[counter];
    }
    // the optional title is LaTeX like any text — parsed (its math gets the user's macros, its
    // \textbf is formatting), not pasted in as source (R70 #4: `[\textbf{Convexity of $\CC_D$}]`
    // came out as code text around an undefined \CC — 1501.00287); all of the lead is bold
    let lead = [{ t: 'txt', s: thmLabel + num + '. ', b: true }];
    if (opt && opt.body.trim()) {
      const title = _ipParseInline(ctx, opt.start + 1, opt.end - 1, { mode: 'heading', depth: 0 }).map(function (r) { return r.t === 'txt' ? Object.assign({}, r, { b: true }) : r; });
      if (title.length && title[0].t === 'txt') title[0] = Object.assign({}, title[0], { s: title[0].s.replace(/^\s+/, '') });
      if (title.length && title[title.length - 1].t === 'txt') title[title.length - 1] = Object.assign({}, title[title.length - 1], { s: title[title.length - 1].s.replace(/\s+$/, '') });
      // amsthm: a proof's optional argument replaces "Proof" itself, and the period is added only
      // when the title does not already end with punctuation (`[Proof (Jarosz).]` printed
      // "Proof (Proof (Jarosz).).", R71 1901.00082)
      const last = title.length ? title[title.length - 1] : null;
      const punct = last && last.t === 'txt' && /[.!?:;]$/.test(last.s);
      lead = name === 'proof'
        ? title.concat([{ t: 'txt', s: punct ? ' ' : '. ', b: true }])
        : [{ t: 'txt', s: thmLabel + num + ' (', b: true }].concat(title, [{ t: 'txt', s: '). ', b: true }]);
      // a plain title stays one run, as before: neighbouring text runs with the same attributes merge
      lead = lead.reduce(function (acc, r) {
        const p = acc[acc.length - 1];
        if (p && p.t === 'txt' && r.t === 'txt' && JSON.stringify(Object.assign({}, p, { s: '' })) === JSON.stringify(Object.assign({}, r, { s: '' }))) acc[acc.length - 1] = Object.assign({}, p, { s: p.s + r.s });
        else acc.push(r);
        return acc;
      }, []);
    }
    if (ctx.docx) lead.unshift({ t: 'txt', s: '\uE010T' + name + '\uE011', b: true });
    if (tmp.length && tmp[0].t === 'para') tmp[0].runs = lead.concat(tmp[0].runs);
    else tmp.unshift({ t: 'para', align: null, runs: lead });
    if (ctx.docx) pushBlock({ t: 'docxmark', docx: { thm: 'start', env: name } });     // R213: a preview never cuts inside a theorem
    for (let k = 0; k < tmp.length; k++) pushBlock(tmp[k]);
    if (ctx.docx) pushBlock({ t: 'docxmark', docx: { thm: 'end' } });
    return after;
  }
