  // except picture-like ones, which stay as source. algorithm / subfigure floats keep their own caption counters
  // R237 docx mode: LaTeX's \begin{list}{label}{set-up} is a list (numbered when the label prints a counter); its set-up
  // (\usecounter \topsep=0pt …) printed as text. trivlist (theorem / proof environments built on it) is its body.
  if (ctx.docx && (name === 'list' || name === 'trivlist')) {
    if (name === 'trivlist') { _ipParseBlocks(ctx, out, bodyStart, bodyEnd, { nesting: o.nesting, align: o.align || null, float: o.float }); return after; }
    const ws = function (q) { for (let m2; (m2 = /^(?:\s+|%[^\n]*(?:\n|$))/.exec(src.slice(q, q + 200))) && m2[0]; ) q += m2[0].length; return q; };
    const gl = _ipReadGroup(src, ws(bodyStart), bodyEnd); let s = gl ? gl.end : bodyStart;
    const gs = _ipReadGroup(src, ws(s), bodyEnd); if (gs) s = gs.end;
    _ipParseList(ctx, out, gl && /\\(arabic|roman|Roman|alph|Alph|the[a-z]+|@arabic)/.test(gl.body) ? 'enumerate' : 'itemize', s, bodyEnd, o);
    return after;
  }
  if (ctx.docx && name === 'algorithmic') {           // R222: algorithmic / algpseudocode as numbered pseudo-code lines
    _ipDocxAlgorithmic(ctx, bodyStart, bodyEnd, pushBlock);
    return after;
  }
