    let s = bodyStart;
    const o1 = _ipReadOptional(src, s, bodyEnd); if (o1) s = o1.end;
    // a width / title argument right after \begin{…} (subfigure{0.5\textwidth}, minipage, tcolorbox[…]{title})
    const g1 = /^\s*\{/.test(src.slice(s, s + 20)) ? _ipReadGroup(src, s, bodyEnd) : null;
    if (g1 && /^\s*[-\d.]*\s*\\?[A-Za-z]*(width|height)\b|^\s*[-\d.]+\s*(pt|cm|mm|in|em|ex)\s*$/.test(g1.body)) s = g1.end;
